function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 200) return 'grid needs 1 to 200 rows.';
  const n = grid.length;
  if (grid.some(row => !Array.isArray(row) || row.length !== n)) return 'grid must be square: every row has n values.';
  if (grid.some(row => row.some(v => !Number.isInteger(v) || v < -99 || v > 99))) return 'Each value is a whole number from -99 to 99.';
  return null;
}

