function minFallingPathSum(grid) {
  const n = grid.length;
  let dp = grid[0].slice();

  for (let row = 1; row < n; row++) {
    let best = Infinity;
    let second = Infinity;
    let bestCol = -1;
    for (let col = 0; col < n; col++) {
      if (dp[col] < best) {
        second = best;
        best = dp[col];
        bestCol = col;
      } else if (dp[col] < second) {
        second = dp[col];
      }
    }

    const next = new Array(n);
    for (let col = 0; col < n; col++) {
      next[col] = grid[row][col] + (col === bestCol ? second : best);
    }
    dp = next;
  }
  return Math.min(...dp);
}

