function minFallingPathSum(grid) {
  // Top-down: the cheapest path from (row, col) to the bottom tries every other column of the next row.
  const n = grid.length;
  const memo = new Map();
  const cheapest = (row, col) => {
    if (row === n - 1) return grid[row][col];
    const key = row * n + col;
    if (memo.has(key)) return memo.get(key);
    let low = Infinity;
    for (let k = 0; k < n; k++) if (k !== col) low = Math.min(low, cheapest(row + 1, k));
    memo.set(key, grid[row][col] + low);
    return grid[row][col] + low;
  };
  let answer = Infinity;
  for (let col = 0; col < n; col++) answer = Math.min(answer, cheapest(0, col));
  return answer;
}

