function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 100 : 1 + pick(6);
  // Narrow value ranges create ties, including two equal minimums in one row.
  const span = rand() < 0.4 ? 2 : 99;
  return [Array.from({ length: n }, () => Array.from({ length: n }, () => pick(2 * span + 1) - span))];
}
